def defense_in_depth(layers, capabilities):
    for layer_name, capability_key in layers:
        if not capabilities.get(capability_key, False):
            return layer_name
    return None


layers = [
    ("perimeter_firewall", "beats_firewall"),
    ("network_segmentation", "beats_segmentation"),
    ("endpoint_detection", "beats_edr"),
    ("least_privilege_acl", "beats_least_privilege"),
]

scenario_a = {"beats_firewall": True, "beats_segmentation": True, "beats_edr": False, "beats_least_privilege": False}
scenario_b = {"beats_firewall": True, "beats_segmentation": True, "beats_edr": True, "beats_least_privilege": False}
scenario_c = {"beats_firewall": True, "beats_segmentation": True, "beats_edr": True, "beats_least_privilege": True}

for label, scenario in [("scenario_a", scenario_a), ("scenario_b", scenario_b), ("scenario_c", scenario_c)]:
    stopped = defense_in_depth(layers, scenario)
    result = f"detenido en {stopped}" if stopped else "compromiso completo: las 4 capas fallaron"
    print(f"{label}: {result}")


def is_within_scope(assigned_scope, action):
    return action in assigned_scope


backup_operator_scope = {"read_files", "create_backup"}
for action in ("read_files", "delete_database"):
    decision = "ALLOW" if is_within_scope(backup_operator_scope, action) else "DENY"
    print(f"{action}: {decision}")
